 await page.evaluate(()=>window.cancelChecklistShare=true);await page.locator('#send-checklist').click();await expect(page.locator('#checklist-share [role=status]')).toHaveText('Sharing cancelled.');await expect(page.locator('#checklist-share')).toBeVisible();
 await page.locator('#copy-shared-checklist').click();expect(await page.evaluate(()=>window.copiedChecklist)).toBe(snapshot);
 const pending=page.waitForEvent('download');await page.locator('#download-shared-checklist').click();const file=await pending;expect(file.suggestedFilename()).toBe('ritual-assist-shraddha-en-snapshot.txt');const target=path.join(dir,'checklist-snapshot.txt');await file.saveAs(target);expect(fs.readFileSync(target,'utf8').replace(/^\uFEFF/,'')).toBe(snapshot);
 await page.evaluate(()=>{Object.defineProperty(navigator,'share',{value:undefined});Object.defineProperty(navigator,'clipboard',{value:undefined});});await page.locator('#send-checklist').click();await expect(page.locator('#checklist-share [role=status]')).toContainText('Copy or download');await page.locator('#copy-shared-checklist').click();await expect(page.locator('#share-checklist-text')).toBeFocused();expect(await page.locator('#share-checklist-text').evaluate(el=>el.selectionEnd-el.selectionStart)).toBe(snapshot.length);
 for(const theme of ['light','dark'])for(const width of [320,390,768,1440]){await page.setViewportSize({width,height:900});await page.evaluate(t=>window.SynapseTheme.write(t),theme);expect(await page.locator('#checklist-share').evaluate(el=>el.scrollWidth<=el.clientWidth)).toBe(true);}
 await page.setViewportSize({width:390,height:844});await page.screenshot({path:'.publish/ritual-checklist-share-mobile.png'});
 await page.goBack();await expect(page.locator('#checklist-share')).toBeHidden();await expect(page.locator('#share-checklist')).toBeFocused();await page.goForward();await expect(page.locator('#checklist-share')).toBeVisible();await page.keyboard.press('Escape');await expect(page.locator('#checklist-share')).toBeHidden();
 await chooseInterfaceLanguage(page,'hi');await page.locator('#share-checklist').click();await expect(page.locator('#checklist-share')).toContainText('साझा करने से पहले');await expect(page.locator('#share-checklist-text')).toHaveValue(/जिम्मेदारी/);await page.locator('#close-checklist-share').click();await expect(page.locator('#checklist-share')).toBeHidden();await chooseInterfaceLanguage(page,'en');await page.evaluate(()=>{Object.defineProperty(navigator,'share',{value:async data=>{window.sharedGuideLink=data;}});});await page.locator('#share-checklist').click();await page.locator('#share').click();const guideLink=await page.evaluate(()=>window.sharedGuideLink);expect(guideLink.url).toContain('guide=shraddha');expect(guideLink.text).not.toContain('Family water');expect(guideLink.text).not.toContain('Asha');
